def _apply_rls() -> None:
    for table in _TENANT_TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(
            f"""
            CREATE POLICY {table}_tenant_isolation ON {table}
            USING (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid)
            WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid)
            """
        )
        op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON {table} TO logistics_app, logistics_worker")

    # Worker 队列消息只含 run_id 与 epoch。用受限函数反查租户，
    # 只返回 tenant_id，不给 Worker 开放业务表的无租户直读。
    op.execute(
        """
        CREATE OR REPLACE FUNCTION worker_tenant_of_run(p_run_id uuid) RETURNS uuid
        LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
            SELECT tenant_id FROM runs WHERE id = p_run_id
        $$
        """
    )
    op.execute(
        """
        CREATE OR REPLACE FUNCTION worker_tenant_of_continuation(p_id uuid) RETURNS uuid
        LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
            SELECT tenant_id FROM assistant_continuations WHERE id = p_id
        $$
        """
    )
    op.execute("REVOKE ALL ON FUNCTION worker_tenant_of_run(uuid) FROM PUBLIC")
    op.execute("REVOKE ALL ON FUNCTION worker_tenant_of_continuation(uuid) FROM PUBLIC")
    op.execute("GRANT EXECUTE ON FUNCTION worker_tenant_of_run(uuid) TO logistics_worker, logistics_app")
    op.execute("GRANT EXECUTE ON FUNCTION worker_tenant_of_continuation(uuid) TO logistics_worker, logistics_app")

    # Task Spec 与参与原件集合一经创建不可改（数据方案 2.6 节），
    # 由触发器兜底而不仅靠路由层约定。
    op.execute(
        """
        CREATE OR REPLACE FUNCTION forbid_run_spec_update() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF NEW.task_spec IS DISTINCT FROM OLD.task_spec
               OR NEW.task_spec_hash IS DISTINCT FROM OLD.task_spec_hash
               OR NEW.workflow_type IS DISTINCT FROM OLD.workflow_type
               OR NEW.workflow_version IS DISTINCT FROM OLD.workflow_version
               OR NEW.draft_task_id IS DISTINCT FROM OLD.draft_task_id
               OR NEW.case_id IS DISTINCT FROM OLD.case_id THEN
                RAISE EXCEPTION 'Run 的 Task Spec 与输入冻结后不可修改' USING ERRCODE = 'check_violation';
            END IF;
            RETURN NEW;
        END $$
        """
    )
    op.execute(
        "CREATE TRIGGER trg_runs_freeze_spec BEFORE UPDATE ON runs "
        "FOR EACH ROW EXECUTE FUNCTION forbid_run_spec_update()"
    )
    op.execute(
        """
        CREATE OR REPLACE FUNCTION forbid_row_update() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            RAISE EXCEPTION '% 为只追加表，不允许更新', TG_TABLE_NAME USING ERRCODE = 'check_violation';
        END $$
        """
    )
    # 参与原件、业务版本、引用快照只追加
    for table in ("run_documents", "business_revisions", "reference_snapshots", "run_events", "turn_events"):
        op.execute(
            f"CREATE TRIGGER trg_{table}_append_only BEFORE UPDATE ON {table} "
            f"FOR EACH ROW EXECUTE FUNCTION forbid_row_update()"
        )


def _drop_rls() -> None:
    for table in ("run_documents", "business_revisions", "reference_snapshots", "run_events", "turn_events"):
        op.execute(f"DROP TRIGGER IF EXISTS trg_{table}_append_only ON {table}")
    op.execute("DROP TRIGGER IF EXISTS trg_runs_freeze_spec ON runs")
    op.execute("DROP FUNCTION IF EXISTS forbid_row_update()")
    op.execute("DROP FUNCTION IF EXISTS forbid_run_spec_update()")
    op.execute("DROP FUNCTION IF EXISTS worker_tenant_of_continuation(uuid)")
    op.execute("DROP FUNCTION IF EXISTS worker_tenant_of_run(uuid)")
    for table in _TENANT_TABLES:
        op.execute(f"DROP POLICY IF EXISTS {table}_tenant_isolation ON {table}")
